/*
 * Minimal HTMX-subset shim — vendored, no CDN dependency (design §7).
 *
 * This is NOT upstream htmx. It implements exactly the subset the tacapes
 * dashboard uses: hx-get / hx-post, hx-trigger (click, submit, "load",
 * "every Ns", "<event> from:body"), hx-target, hx-swap (innerHTML | outerHTML),
 * hx-select, and the HX-Trigger response header. To get the full htmx feature
 * set, drop the real htmx.min.js in here instead — the attribute API is
 * source-compatible for everything above.
 */
(function () {
  "use strict";

  // body-event listeners, keyed "<elementId>|<event>" so a re-processed
  // element (e.g. #book after an outerHTML swap) replaces — not duplicates —
  // its listener.
  var bodyListeners = {};

  function attr(el, name) { return el.getAttribute(name); }

  function targetOf(el) {
    var sel = attr(el, "hx-target");
    if (!sel || sel === "this") return el;
    return document.querySelector(sel);
  }

  function swap(el, html) {
    var target = targetOf(el);
    if (!target) return;
    var mode = attr(el, "hx-swap") || "innerHTML";
    var select = attr(el, "hx-select");
    var content = html;
    if (select) {
      var doc = new DOMParser().parseFromString(html, "text/html");
      var picked = doc.querySelector(select);
      content = picked ? picked.outerHTML : "";
    }
    if (mode === "outerHTML") {
      var holder = document.createElement("div");
      holder.innerHTML = content;
      var nodes = Array.prototype.slice.call(holder.childNodes);
      var parent = target.parentNode;
      var anchor = target.nextSibling;
      parent.removeChild(target);
      nodes.forEach(function (n) { parent.insertBefore(n, anchor); });
      nodes.forEach(function (n) { if (n.nodeType === 1) process(n); });
    } else {
      target.innerHTML = content;
      process(target);
    }
  }

  function issue(el) {
    var url = attr(el, "hx-get") || attr(el, "hx-post");
    if (!url) return;
    var method = attr(el, "hx-get") ? "GET" : "POST";
    var opts = { method: method, headers: { "HX-Request": "true" } };
    if (method === "POST" && el.tagName === "FORM") {
      opts.body = new URLSearchParams(new FormData(el));
    }
    fetch(url, opts).then(function (resp) {
      var trigger = resp.headers.get("HX-Trigger");
      return resp.text().then(function (text) {
        if (trigger) {
          trigger.split(",").forEach(function (ev) {
            document.body.dispatchEvent(
              new CustomEvent(ev.trim(), { bubbles: true })
            );
          });
        }
        swap(el, text);
      });
    }).catch(function (e) {
      console.error("hx request failed", url, e);
    });
  }

  function bind(el) {
    if (el._hxBound) return;
    el._hxBound = true;
    var spec = attr(el, "hx-trigger");
    var triggers = spec
      ? spec.split(",").map(function (s) { return s.trim(); })
      : [el.tagName === "FORM" ? "submit" : "click"];

    triggers.forEach(function (t) {
      if (t.indexOf("every ") === 0) {
        var secs = parseFloat(t.slice(6));
        if (secs > 0) setInterval(function () { issue(el); }, secs * 1000);
      } else if (t === "load") {
        issue(el);
      } else if (t.indexOf(" from:body") !== -1) {
        var ev = t.split(" ")[0];
        var key = (el.id || "anon") + "|" + ev;
        if (bodyListeners[key]) {
          document.body.removeEventListener(ev, bodyListeners[key]);
        }
        var handler = function () { issue(el); };
        bodyListeners[key] = handler;
        document.body.addEventListener(ev, handler);
      } else {
        el.addEventListener(t, function (e) {
          if (e && e.preventDefault) e.preventDefault();
          issue(el);
        });
      }
    });
  }

  function process(root) {
    if (
      root.nodeType === 1 &&
      (root.hasAttribute("hx-get") || root.hasAttribute("hx-post"))
    ) {
      bind(root);
    }
    if (root.querySelectorAll) {
      Array.prototype.forEach.call(
        root.querySelectorAll("[hx-get],[hx-post]"), bind
      );
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      process(document.body);
    });
  } else {
    process(document.body);
  }
})();
